<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {api} from '../lib/api'
const emit=defineEmits(['close']),dialog=ref(null),today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date()),date=ref(today),note=ref({day:today,title:'',body:'',version:0,updated_at:null}),items=ref([]),loading=ref(false),saving=ref(false),error=ref(''),status=ref(''),saved=ref(JSON.stringify(['',''])),dirty=computed(()=>JSON.stringify([note.value.title,note.value.body])!==saved.value);let timer,alive=true
function snapshot(){return JSON.stringify([note.value.title,note.value.body])}
async function load(day){loading.value=true;error.value='';try{const r=await api('/notes?date='+encodeURIComponent(day));if(!alive)return;note.value=r.note;date.value=day;items.value=r.items;saved.value=snapshot();status.value=r.note.updated_at?'저장된 메모를 불러왔어요.':'오늘의 배움을 자유롭게 적어 보세요.'}catch(e){if(alive)error.value=e.message}finally{if(alive)loading.value=false}}
async function save(){clearTimeout(timer);if(saving.value||loading.value)return false;if(!dirty.value)return true;saving.value=true;error.value='';try{const r=await api('/notes/'+date.value,{method:'PUT',body:{title:note.value.title,body:note.value.body,version:note.value.version}});if(!alive)return false;note.value=r.note;items.value=r.items;saved.value=snapshot();status.value='저장했어요 · '+new Date(r.note.updated_at).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul'});return true}catch(e){if(alive){error.value=e.message;status.value='저장하지 못했어요. 작성한 내용은 이 화면에 남아 있습니다.'}return false}finally{if(alive)saving.value=false}}
async function change(day){if(!day||saving.value||loading.value)return;if(dirty.value&&!await save())return;await load(day)}
function shiftDay(offset){const d=new Date(date.value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+offset);change(d.toISOString().slice(0,10))}
async function close(){if(saving.value||loading.value)return;if(dirty.value&&!await save())return;dialog.value.close();emit('close')}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(()=>[note.value.title,note.value.body],()=>{clearTimeout(timer);if(!loading.value&&!saving.value&&dirty.value)timer=setTimeout(save,1200)},{flush:'post'})
onMounted(()=>{dialog.value.showModal();load(today);window.addEventListener('beforeunload',beforeUnload)})
onUnmounted(()=>{alive=false;clearTimeout(timer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><dialog ref="dialog" class="daily-notes-dialog" aria-label="오늘 배운 내용 정리하기" @cancel.prevent="close"><section class="daily-notes-book"><header class="daily-notes-heading"><span class="notes-dex-lens" aria-hidden="true"></span><div class="notes-dex-title"><span class="eyebrow">MY STUDY NOTE</span><h2>오늘 배운 내용 정리하기</h2></div><span class="notes-dex-ball" aria-hidden="true"></span><button type="button" class="light" :disabled="saving||loading" aria-label="메모장 닫기" @click="close">닫기 ✕</button></header><div class="daily-notes-layout"><aside class="daily-notes-history"><h3>지난 메모</h3><button class="light" :disabled="saving||loading" @click="change(today)">오늘로 돌아가기</button><p v-if="!items.length">첫 번째 배움을 기록해 보세요.</p><button v-for="item in items" :key="item.day" :class="{selected:date===item.day}" :disabled="saving||loading" @click="change(item.day)"><b>{{item.day}}</b><span>{{item.title||'제목 없는 메모'}}</span></button></aside><form id="daily-note-form" class="daily-notes-editor" @submit.prevent="save"><div class="daily-note-date"><label>날짜<input type="date" :value="date" :disabled="saving||loading" @change="change($event.target.value)"/></label><span>{{note.body.length.toLocaleString()}} / 20,000자</span></div><label class="sr-only" for="daily-note-title">메모 제목</label><input id="daily-note-title" v-model="note.title" maxlength="100" :disabled="saving||loading" placeholder="오늘 배운 내용의 제목"/><label class="sr-only" for="daily-note-body">오늘 배운 내용</label><textarea id="daily-note-body" v-model="note.body" maxlength="20000" :disabled="saving||loading" placeholder="오늘 새롭게 알게 된 것&#10;&#10;기억하고 싶은 개념&#10;&#10;아직 헷갈리는 것"/><p v-if="error" class="note-error" role="alert">{{error}} <button type="button" class="text-button" :disabled="saving||loading" @click="load(date)">서버 메모 다시 불러오기</button></p></form></div><footer class="daily-notes-actions"><div class="notes-date-pad"><button type="button" :disabled="saving||loading" aria-label="이전 날짜" @click="shiftDay(-1)">◀</button><button type="button" :disabled="saving||loading" @click="change(today)">오늘</button><button type="button" :disabled="saving||loading" aria-label="다음 날짜" @click="shiftDay(1)">▶</button></div><span class="notes-status-lcd" role="status"><small>STUDY LOG / {{date}}</small>{{loading?'불러오는 중…':saving?'저장 중…':dirty?'작성 중 · 자동 저장 대기':status}}</span><button class="notes-save-key" type="submit" form="daily-note-form" aria-label="메모 저장" :disabled="saving||loading||!dirty"><span aria-hidden="true">✓</span></button></footer></section></dialog></template>
